const gated=$input.all().map(i=>i.json);
const queue=[];
for(const g of gated){
  for(const a of (g.identity_assets||[])) queue.push({route:'DOWNLOAD',edit_session_id:g.edit_session_id,
    asset_id:a.asset_id,role:a.role,DRIVE_FILE_ID:a.drive_file_id,ARQUIVO:a.file_name,
    worker_source_path:a.source_path,expected_sha256:a.expected_sha256,mime_type:a.mime_type});
}
if(!queue.length)return [{json:{route:'NO_IDENTITY'}}];
const keys=new Set();
for(const a of queue){const key=a.edit_session_id+'|'+a.role;if(keys.has(key))throw new Error('SM3_07F_V3_IDENTITY_QUEUE_DUPLICATE:'+key);keys.add(key)}
return queue.map(json=>({json}));

const rows=$input.all().map(i=>i.json), item=$('ASSERT — EDITORIAL PLAN SHEET COMMITTED').first().json, a=item.artifactRow;
const matches=rows.filter(r=>String(r.ARTIFACT_ID||'')===a.ARTIFACT_ID);
if(matches.length!==1||String(matches[0].MANIFEST_SHA256||'')!==a.MANIFEST_SHA256||String(matches[0].STATUS||'')!=='VERIFIED_CANDIDATE'||String(matches[0].ARTIFACT_TYPE||'')!=='CAROUSEL_IMAGE_SET')throw new Error('SM3_08E_ARTIFACT_SHEET_FAILED:'+a.ARTIFACT_ID);
return [{json:{status:'SM3_08E_NATIVE_FORMAT_EDITORIAL_COMMITTED',artifact_id:a.ARTIFACT_ID,editorial_plan_id:a.EDITORIAL_PLAN_ID,revision:a.REVISION,manifest_sha256:a.MANIFEST_SHA256,asset_count:a.ASSET_COUNT,assets:item.assets,review_asset:item.review_asset}}];
